package io.github.jesterportfolio.hearth.features;
import io.github.jesterportfolio.hearth.combat.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
final class RecoveryLedgerTest {
    final UUID battle=UUID.randomUUID(),world=UUID.randomUUID();final CombatContent.Exit exit=new CombatContent.Exit(new FieldContent.Point(3.5,64,3.5),90,0,.5,List.of(new CombatContent.Effect("RESISTANCE",0,40)));
    RecoveryLedger.State active(){return RecoveryLedger.start((RecoveryLedger.State)null,battle,null,world,exit,"SURVIVAL");}
    @Test void activeOrUnconfirmedMoveIsHoldWhileOnlyConfirmedEndCanReturn(){var a=active();assertEquals(RecoveryLedger.Action.HOLD,RecoveryLedger.restart(a));var end=RecoveryLedger.end(a,battle);assertEquals(RecoveryLedger.Action.RETURN,RecoveryLedger.restart(end));var claim=UUID.randomUUID();var moving=RecoveryLedger.claim(end,battle,claim);assertEquals(RecoveryLedger.Action.HOLD,RecoveryLedger.restart(moving));assertEquals(RecoveryLedger.Action.NONE,RecoveryLedger.restart(RecoveryLedger.done(moving,battle,claim)));}
    @Test void onlyKnownParentCanReplaceAnActiveBattleAndDoneCannotResurrect(){var a=active();assertThrows(IllegalStateException.class,()->RecoveryLedger.start(a,UUID.randomUUID(),UUID.randomUUID(),world,exit,"SURVIVAL"));var child=UUID.randomUUID();assertEquals(child,RecoveryLedger.start(a,child,battle,world,exit,"SURVIVAL").attempt());var claim=UUID.randomUUID();var done=RecoveryLedger.done(RecoveryLedger.claim(RecoveryLedger.end(a,battle),battle,claim),battle,claim);assertThrows(IllegalStateException.class,()->RecoveryLedger.start(done,battle,null,world,exit,"SURVIVAL"));}
    @Test void sameRequestsAreIdempotentAndOldClaimsCannotFinishDifferentMove(){var pending=RecoveryLedger.end(active(),battle);assertSame(pending,RecoveryLedger.end(pending,battle));var id=UUID.randomUUID();var claimed=RecoveryLedger.claim(pending,battle,id);assertEquals(claimed,RecoveryLedger.claim(claimed,battle,id));assertThrows(IllegalStateException.class,()->RecoveryLedger.claim(claimed,battle,UUID.randomUUID()));assertThrows(IllegalStateException.class,()->RecoveryLedger.done(claimed,battle,UUID.randomUUID()));}
    @Test void claimRequiresConfirmedEndAndMatchingBattle(){assertThrows(IllegalStateException.class,()->RecoveryLedger.claim(active(),battle,UUID.randomUUID()));assertThrows(IllegalStateException.class,()->RecoveryLedger.end(active(),UUID.randomUUID()));assertThrows(IllegalStateException.class,()->RecoveryLedger.done(active(),battle,UUID.randomUUID()));}
    @Test void savedPolicyAndWorldArePreservedAcrossFreshDecode(){var pending=RecoveryLedger.end(active(),battle);assertEquals(pending,RecoveryLedger.decode(RecoveryLedger.encode(pending)));assertEquals(exit,RecoveryLedger.decode(RecoveryLedger.encode(pending)).exit());}
    @Test void malformedOrTrailingRecordsAreNeverTreatedAsNoPendingReturn(){assertThrows(IllegalArgumentException.class,()->RecoveryLedger.decode(new byte[0]));var bytes=Arrays.copyOf(RecoveryLedger.encode(active()),1000);assertThrows(IllegalArgumentException.class,()->RecoveryLedger.decode(bytes));assertThrows(IllegalArgumentException.class,()->new RecoveryLedger.State(battle,RecoveryLedger.Phase.RETURN_PENDING,world,exit,"CREATIVE",null));}
}
